-- composition of rule kernels L:eliminate_join x L:extract_equijoin_predicate (datafusion), template not_exists
SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT a2.c0 AS c0, (1.0 / 3)::float8 AS c1 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3))) SELECT 1.5::numeric AS c0, TRUE AS c1 FROM t4 AS a3 WHERE (('2024-12-31'::date = '2000-01-01'::date) OR ((ABS (3))::bigint >= LEAST (10::bigint, (SELECT COUNT (*) FROM cte1 AS a4))))) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb) = 0 THEN (SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT a2.c0 AS c0, (1.0 / 3)::float8 AS c1 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3))) SELECT 1.5::numeric AS c0, TRUE AS c1 FROM t4 AS a3 WHERE (('2024-12-31'::date = '2000-01-01'::date) OR ((ABS (3))::bigint >= LEAST (10::bigint, (SELECT COUNT (*) FROM cte1 AS a4))))) AS ka) ELSE 0 END
